using System.ComponentModel.DataAnnotations;using Essco.Application.HumanResources;using Essco.Application.Security;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;
namespace Essco.Web.Pages.Employees;
[Authorize(Policy=Permissions.Payroll)]public sealed class CompensationModel(EmployeeService employees,EmployeeCompensationService service):PageModel
{public string EmployeeId{get;private set;}="";public string EmployeeName{get;private set;}="";public IReadOnlyCollection<SalaryIncrease>Increases{get;private set;}=[];public IReadOnlyCollection<EmployeeAdditional>Additionals{get;private set;}=[];public IReadOnlyList<string>AdditionalTypes=>EmployeeCompensationService.AdditionalTypes;[BindProperty]public IncreaseForm Increase{get;set;}=new();[BindProperty]public AdditionalForm Additional{get;set;}=new();[TempData]public string?StatusMessage{get;set;}
public async Task<IActionResult>OnGetAsync(string id,CancellationToken t){if(!await Load(id,t))return NotFound();Increase.Date=DateOnly.FromDateTime(DateTime.Today);return Page();}public async Task<IActionResult>OnPostIncreaseAsync(string id,CancellationToken t){var ok=await service.AddIncreaseAsync(new(id,Increase.Date,Increase.Percentage,Increase.Reason??"",User.Identity?.Name??"web"),t);StatusMessage=ok?"Aumento aplicado y salario actualizado.":"Revise porcentaje, fecha y motivo.";return RedirectToPage(new{id});}public async Task<IActionResult>OnPostAdditionalAsync(string id,CancellationToken t){var ok=await service.AddAdditionalAsync(id,Additional.Type??"",Additional.Amount,t);StatusMessage=ok?"Adicional registrado.":"Seleccione un tipo válido y un monto mayor que cero.";return RedirectToPage(new{id});}public async Task<IActionResult>OnPostAnnulAdditionalsAsync(string id,CancellationToken t){StatusMessage=await service.AnnulAdditionalsAsync(id,t)?"Adicionales activos anulados.":"No había adicionales activos.";return RedirectToPage(new{id});}private async Task<bool>Load(string id,CancellationToken t){var file=await employees.GetAsync(id,t);if(file is null)return false;EmployeeId=id;EmployeeName=file.Employee.Name;Increases=await service.IncreasesAsync(id,t);Additionals=await service.AdditionalsAsync(id,t);return true;}public sealed class IncreaseForm{[Display(Name="Fecha")]public DateOnly Date{get;set;}[Range(.01,100),Display(Name="Porcentaje de aumento")]public decimal Percentage{get;set;}[Required,Display(Name="Motivo")]public string?Reason{get;set;}}public sealed class AdditionalForm{[Required,Display(Name="Tipo")]public string?Type{get;set;}[Range(.01,double.MaxValue),Display(Name="Monto")]public decimal Amount{get;set;}}}
